resources.string:
"class MyApplication : Application() {
 override fun onCreate() {
 super.onCreate()
 DirectStreamClient.initialize(
 this,
 DirectStreamConfiguration(
 provider = configuredProvider,
 participantName = null,
 returnActivity = MainActivity::class.java
 )
 )
 }
}
// configuredProvider uses your host-owned Firebase/Worker configuration.
// See README Quick start for the complete provider example."

"val calls = DirectStreamClient.current()
// Run in a host-owned coroutine after login:
when (val result = calls.activate(participantName = currentUser.displayName)) {
 CallResult.Success -> Unit // Observe calls.registration for the code.
 is CallResult.Failure -> showError(result.error)
}
// Profile edit: calls.updateParticipantName(newDisplayName)
// Logout: await calls.deactivate(); remove your backend user/device binding.
// Handle each result; offline revocation remains cleanup pending."

"val calls = DirectStreamClient.current()
calls.registration.collectLatest { registration ->
 registration.device?.let { device ->
 val proof = calls.ownershipProof()
 // Host backend verifies proof and SDK code ownership.
 // Then bind device.code to the signed-in user.
 }
}
// Re-sync after regeneration. Never log proof credentials."

"// Inside DirectStreamHost(client = calls) { callUi -> ... }:
ContactsScreen(onCall = { code ->
 callUi.startCall(code, CallMode.Video)
}, onAudioCall = { code ->
 callUi.startCall(code, CallMode.Audio)
})
// callUi performs permission/unlock preflight; calls is the client."

"val calls = DirectStreamClient.current()
MaterialTheme {
 DirectStreamHost(client = calls) { callUi ->
 ContactsScreen(onCall = { deviceCode ->
 callUi.startCall(deviceCode, CallMode.Video)
 })
 }
}
// Use callContent for custom screens.
// Your app owns its ordinary navigation."

"val calls = DirectStreamClient.current()
// At startup/sign-in, forward the existing token too:
calls.updatePushToken(FirebaseMessaging.getInstance().token.await())
// Forward from your own FirebaseMessagingService:
// Coroutine scope appropriate to the service callback:
calls.updatePushToken(token)
calls.handlePush(message.data)
// The SDK declares no FirebaseMessagingService.
// DirectStreamHost owns lifecycle and notification routing.
// Never approve a call from a push payload."

"val calls = DirectStreamClient.current()
when (val result = calls.regenerateCode()) {
 CallResult.Success -> {
 // The state collector re-syncs the replacement code.
 // Old code is revoked; pending incoming requests cancel.
 // Already approved calls continue.
 }
 is CallResult.Failure -> showError(result.error)
}"
